surfer.group.traverse(o => { if (o.isMesh) meshes++; });
console.log('surfer meshes:', meshes);
// simulate 10s of animation at 60fps
for (let f = 0; f < 600; f++) {
  const t = f / 60;
  ocean.update(t);
  clouds.update(1/60);
  birds.update(t);
  const px = Math.sin(t * 0.24) * 1.4, pz = Math.sin(t * 0.17 + 1.0) * 0.9;
  surfer.group.position.set(px, waveHeight(px, pz, t) + 0.1, pz);
  surfer.update(t, 0.1 * Math.sin(t));
}
let bad = 0;
surfer.group.updateMatrixWorld(true);
const v = new THREE.Vector3();
surfer.group.traverse(o => { if (o.isMesh) { o.getWorldPosition(v); if (!isFinite(v.x+v.y+v.z)) bad++; } });
const p = ocean.mesh.geometry.attributes.position;
for (let i = 0; i < p.count; i++) { if (!isFinite(p.getY(i))) bad++; }
if (bad) throw new Error(bad + ' non-finite vertices');
console.log('600-FRAME HEADLESS SIM OK');
"

